/**
 * WorkflowAgent E2E — minimaxh3_t2v_i2v_ref2v_advanced_film_making_foxydit
 *
 * Auto-generated by wf-convert; revised for correct GPU config (h100).
 *
 * T2V mode — no image/video fixture inputs, only a structured text prompt param.
 *
 * Two renders check the fps snap of the graph: fps 24 (native frames, RIFE skipped) and fps 48 (RIFE 2x),
 * both at an unchanged 5 s duration. E2E_RUNS=fps-24,fps-48 selects the runs.
 *
 * Run inside the harness container (standard fat-image deployment):
 *   docker exec -it harness golem repl \
 *     --script-file /work/workflows/minimaxh3_t2v_i2v_ref2v_advanced_film_making_foxydit/e2e-test.ts --yes
 *
 * Dev-tree fallback (local golem server, not via fat image):
 *   WORK_DIR=/path/to/repo-root \
 *   source video-harness/.env && cd video-harness && \
 *   golem repl --script-file ../workflows/minimaxh3_t2v_i2v_ref2v_advanced_film_making_foxydit/e2e-test.ts --yes
 */

// ── CONFIG ───────────────────────────────────────────────────────────────────
const WF_NAME = "minimaxh3_t2v_i2v_ref2v_advanced_film_making_foxydit";
const GPU_TYPE = "h100"; // per workflow.yaml gpu_types: [a100, h100, blackwell]
const TIMEOUT_SEC = 5400; // 90 min per attempt
const PROVISION_TIMEOUT_MS = 60 * 60 * 1000; // 60 min (includes model download ~37 GB)
const RENDER_TIMEOUT_MS = 90 * 60 * 1000; // 90 min for render
const RENDER_POLL_MS = 30_000;

const COMPUTE_BACKEND = process.env.COMPUTE_BACKEND ?? "modal";
const S3_BUCKET = process.env.S3_BUCKET ?? "";
const AWS_REGION = process.env.AWS_REGION ?? "us-east-1";
const AWS_ACCESS_KEY = process.env.AWS_ACCESS_KEY ?? "";
const AWS_SECRET_KEY = process.env.AWS_SECRET_KEY ?? "";
const HF_TOKEN = process.env.HF_TOKEN ?? "";

const missing = [
  ["S3_BUCKET", S3_BUCKET],
  ["AWS_ACCESS_KEY", AWS_ACCESS_KEY],
  ["AWS_SECRET_KEY", AWS_SECRET_KEY],
]
  .filter(([, v]) => !v)
  .map(([k]) => k);
if (missing.length)
  throw new Error(`Missing required env vars: ${missing.join(", ")}`);

// ── golem-ts-bridge //v1 double-slash workaround ──────────────────────────────
// The golem CLI's `-E release` (custom server) config normalizes the server URL
// with a trailing slash (e.g. "http://localhost:9881/"); golem-ts-bridge's
// createAgent()/invokeAgent() concatenate `${baseUrl}/v1/...` verbatim, producing
// "http://localhost:9881//v1/agents/create-agent". The fat-image container has no
// nginx in front of golem to normalize this (unlike the docker-compose dev stack),
// so every agent RPC 404s with "Not Found, not found". Patch it at the fetch layer.
const _origFetch = globalThis.fetch;
(globalThis as any).fetch = (input: any, init?: any) => {
  if (typeof input === "string") input = input.replace(/([^:])\/\/v1\//, "$1/v1/");
  return _origFetch(input, init);
};

// ── FIXTURE FILES ─────────────────────────────────────────────────────────────
const _path = require("node:path") as typeof import("node:path");
const WORK_DIR = process.env.WORK_DIR ?? "/work";
const FIXTURE_DIR = _path.join(WORK_DIR, "workflows", WF_NAME);

// Models are sourced from workflow.yaml via agent.loadFromContent() — no hardcoded WF_MODELS needed.

// ── Render profile ────────────────────────────────────────────────────────────
const RENDER_PROFILE = {
  tier: "standard",
  profile: {
    compute: {
      backend: COMPUTE_BACKEND,
      gpuType: GPU_TYPE,
      timeoutSec: TIMEOUT_SEC,
      maxAttempts: 2,
    },
  },
};

// ── MP4 timing probe ──────────────────────────────────────────────────────────
// Frame rate and duration of the first video track of an mp4 buffer: the mdhd timescale /
// duration and the stts sample count (the REPL host has no ffprobe).
function mp4VideoTiming(
  buf: Buffer,
): { fps: number; durationSeconds: number; frames: number } | null {
  const boxes = (start: number, end: number): [string, number, number][] => {
    const out: [string, number, number][] = [];
    let at = start;
    while (at + 8 <= end) {
      let size = buf.readUInt32BE(at);
      let header = 8;
      if (size === 1) {
        size = Number(buf.readBigUInt64BE(at + 8));
        header = 16;
      } else if (size === 0) size = end - at;
      if (size < header || at + size > end) break;
      out.push([buf.toString("latin1", at + 4, at + 8), at + header, at + size]);
      at += size;
    }
    return out;
  };
  const child = (box: [string, number, number] | undefined, type: string) =>
    box ? boxes(box[1], box[2]).find((b) => b[0] === type) : undefined;
  const moov = boxes(0, buf.length).find((b) => b[0] === "moov");
  for (const trak of moov ? boxes(moov[1], moov[2]) : []) {
    if (trak[0] !== "trak") continue;
    const mdia = child(trak, "mdia");
    const hdlr = child(mdia, "hdlr");
    if (!hdlr || buf.toString("latin1", hdlr[1] + 8, hdlr[1] + 12) !== "vide") continue;
    const mdhd = child(mdia, "mdhd");
    const stts = child(child(child(mdia, "minf"), "stbl"), "stts");
    if (!mdhd || !stts) return null;
    const v1 = buf[mdhd[1]] === 1;
    const timescale = buf.readUInt32BE(mdhd[1] + (v1 ? 20 : 12));
    const duration = v1 ? Number(buf.readBigUInt64BE(mdhd[1] + 24)) : buf.readUInt32BE(mdhd[1] + 16);
    let frames = 0;
    for (let i = 0; i < buf.readUInt32BE(stts[1] + 4); i++) frames += buf.readUInt32BE(stts[1] + 8 + i * 8);
    const durationSeconds = duration / timescale;
    return { fps: frames / durationSeconds, durationSeconds, frames };
  }
  return null;
}

// Playback seconds of a MiniMax H3 clip of `seconds`: the graph's frame count at the native 24 fps
// (max(5, round(s x 24)) padded to 17k+5). RIFE 2x (2n-1 frames at 48) plays 1/48 s shorter.
function h3ClipSeconds(seconds: number): number {
  const n = Math.max(5, Math.round(seconds * 24));
  return (n + ((5 - (n % 17)) % 17 + 17) % 17) / 24;
}

// The fps snap of the graph: an output rate above 24 gives RIFE 2x frames at 48, 24 or below the
// native frames at 24 - and the clip lasts the requested duration either way.
function checkFpsSnap(label: string, buf: Buffer, expectFps: 24 | 48, seconds: number): void {
  const t = mp4VideoTiming(buf);
  check(
    `${label}: output encoded at ${expectFps} fps (${expectFps === 48 ? "RIFE 2x" : "native frames, no RIFE"})`,
    !!t && Math.abs(t.fps - expectFps) < 0.5,
    JSON.stringify(t),
  );
  const expectSeconds = h3ClipSeconds(seconds);
  check(
    `${label}: duration unchanged by the rate (${expectSeconds.toFixed(3)} s +- 0.1)`,
    !!t && Math.abs(t.durationSeconds - expectSeconds) < 0.1,
    JSON.stringify(t),
  );
}

// ── Helpers ───────────────────────────────────────────────────────────────────
const _nodeFs = require("node:fs") as typeof import("node:fs");
const failures: string[] = [];

function check(name: string, cond: boolean, detail: string): void {
  console.log(`  ${cond ? "✓" : "✗"} ${name} — ${detail}`);
  if (!cond) failures.push(`${name}: ${detail}`);
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

async function pollUntilDone(agent: any, renderId: string): Promise<any> {
  const deadline = Date.now() + RENDER_TIMEOUT_MS;
  let lastPhase = "";
  while (Date.now() < deadline) {
    const json = await agent.runStatus(renderId);
    const result = JSON.parse(json ?? "null");
    if (!result)
      throw new Error(`runStatus returned null for renderId "${renderId}"`);
    if (result.phase !== lastPhase) {
      console.log(
        `    phase=${result.phase}  attempts=${result.attempts ?? 0}`,
      );
      lastPhase = result.phase;
    }
    if (result.phase === "succeeded") return result;
    if (result.phase === "failed") {
      const f = result.failure ?? {};
      throw new Error(
        `render failed: kind=${f.kind ?? "?"} — ${f.message ?? "(no message)"}`,
      );
    }
    await sleep(RENDER_POLL_MS);
  }
  throw new Error(`render timed out after ${RENDER_TIMEOUT_MS / 1000}s`);
}

// ── Agent ─────────────────────────────────────────────────────────────────────
const agent = await WorkflowAgent.get(
  WF_NAME,
  `e2e-${WF_NAME}-${Date.now()}`,
);

async function teardownAll(): Promise<void> {
  console.log(
    "\n── Teardown ─────────────────────────────────────────────────────",
  );
  try {
    await agent.teardown();
    console.log("  ✓ teardown() completed");
    const st = JSON.parse(await agent.backendStatus());
    check(
      "status after teardown is not provisioned",
      st.status !== "provisioned",
      st.status,
    );
  } catch (err) {
    console.log(`  ✗ teardown() threw: ${err}`);
    failures.push(`teardown: ${err}`);
  }
}

// ── Test execution ────────────────────────────────────────────────────────────
try {
  console.log(`=== WorkflowAgent E2E — ${WF_NAME} ===\n`);

  // 1. Load workflow from local bundle ─────────────────────────────────────────
  // workflow.json and workflow.yaml are read directly from the bind-mounted fixture
  // directory — WorkflowAgent.load() uses workflowJson inline and never fetches sourceUrl.
  console.log(
    "── 1. Load workflow from bundle ─────────────────────────────────",
  );
  const _fs: {
    readFileSync: (p: string, enc: string) => string;
  } = require("node:fs");
  const workflowJson = _fs.readFileSync(
    _path.join(FIXTURE_DIR, "workflow.json"),
    "utf8",
  );
  const workflowYaml = _fs.readFileSync(
    _path.join(FIXTURE_DIR, "workflow.yaml"),
    "utf8",
  );
  console.log(
    `  workflow.json: ${workflowJson.length} bytes   workflow.yaml: ${workflowYaml.length} bytes`,
  );
  check(
    "workflow.json loaded",
    workflowJson.length > 0,
    `${workflowJson.length} bytes`,
  );
  check(
    "workflow.yaml loaded",
    workflowYaml.length > 0,
    `${workflowYaml.length} bytes`,
  );

  // Routes through WorkflowDownloader.buildEntryFromContent() — same path as production workspace.
  const slimManifestJson = await agent.loadFromContent(
    WF_NAME,
    workflowJson,
    workflowYaml,
  );
  const manifest = JSON.parse(slimManifestJson);
  if (manifest.error)
    throw new Error(`loadFromContent failed: ${manifest.error}`);
  console.log(
    `  Loaded: inputs=${manifest.inputs?.length ?? 0} outputs=${manifest.outputs?.length ?? 0}`,
  );
  check(
    "manifest id matches",
    manifest.id === WF_NAME,
    manifest.id ?? "(null)",
  );
  check(
    "no image/video inputs (pure T2V)",
    (manifest.inputs?.length ?? 0) === 0,
    JSON.stringify(manifest.inputs?.map((i: any) => i.name)),
  );
  check(
    "has primary output",
    manifest.outputs?.some((o: any) => o.role === "primary"),
    JSON.stringify(manifest.outputs),
  );

  // 1b. Pre-flight: verify model URLs from YAML ─────────────────────────────────
  console.log(
    "\n── 1b. Pre-flight: verify model URLs ────────────────────────────",
  );
  const _yaml: { parse: (input: string) => any } = require("yaml");
  const parsedYaml = _yaml.parse(workflowYaml);
  for (const model of parsedYaml.models ?? []) {
    for (const f of model.files ?? []) {
      const url = f.url as string;
      if (!url) {
        console.log(`  [skip] ${model.name} — no public URL`);
        continue;
      }
      const headers: Record<string, string> = {};
      if (url.includes("huggingface.co") && HF_TOKEN) {
        headers["Authorization"] = `Bearer ${HF_TOKEN}`;
      }
      const resp = await fetch(url, {
        method: "HEAD",
        redirect: "follow",
        headers,
      });
      check(
        `${model.name} URL resolves`,
        resp.ok,
        `HTTP ${resp.status} — ${url.slice(0, 80)}`,
      );
    }
  }
  if (failures.length > 0)
    throw new Error(`Model URL pre-flight failed:\n${failures.join("\n")}`);

  // 2. Provision ───────────────────────────────────────────────────────────────
  console.log(
    "\n── 2. Provision " + GPU_TYPE + " endpoint ─────────────────────",
  );
  await agent.provision();
  const provDeadline = Date.now() + PROVISION_TIMEOUT_MS;
  let provSummary: any = null;
  while (Date.now() < provDeadline) {
    const st = JSON.parse(await agent.backendStatus());
    if (st.status === "provisioned") {
      provSummary = st;
      break;
    }
    if (st.status === "failed")
      throw new Error(`Provisioning failed: ${st.error}`);
    console.log(`  [${st.status}] dc=${st.dcIndex ?? 0}/${st.dcTotal ?? "?"}`);
    await sleep(25_000);
  }
  if (!provSummary)
    throw new Error(
      `Provision timed out after ${PROVISION_TIMEOUT_MS / 60_000} min`,
    );
  check(
    "provisioned",
    provSummary.status === "provisioned",
    provSummary.status,
  );

  // 3. Read prompt fixture ─────────────────────────────────────────────────────
  // T2V mode: no image/video anchors — only the structured REF2V-format text prompt.
  console.log(
    "\n── 3. Read prompt fixture ───────────────────────────────────────",
  );
  const promptText = _nodeFs
    .readFileSync(_path.join(FIXTURE_DIR, "prompt_positive.txt"), "utf-8")
    .toString()
    .trim();
  check("prompt_positive.txt loaded", promptText.length > 0, `${promptText.length} chars`);

  // 4. Renders, one per output rate ─────────────────────────────────────────
  function _isMp4(b: Uint8Array): boolean {
    // ISO BMFF 'ftyp' box at offset 4
    return b.length >= 8 && b[4] === 0x66 && b[5] === 0x74 && b[6] === 0x79 && b[7] === 0x70;
  }
  function _hexHead(b: Uint8Array, n = 8): string {
    return Array.from(b.slice(0, n)).map((x) => x.toString(16).padStart(2, "0")).join(" ");
  }
  const VIDEO_LENGTH = 5.0;
  const RUNS: { label: string; fps: 24 | 48 }[] = [
    { label: "fps-24", fps: 24 },
    { label: "fps-48", fps: 48 },
  ];
  const wanted = (process.env.E2E_RUNS ?? RUNS.map((r) => r.label).join(",")).split(",");
  for (const run of RUNS.filter((r) => wanted.includes(r.label))) {
    console.log(`\n── 4. ${run.label} ─────────────────────────────────────────────`);
    const renderId = await agent.run(
      JSON.stringify(RENDER_PROFILE),
      JSON.stringify({}),
      JSON.stringify({
        prompt_positive: promptText,
        steps: 4,
        video_length: VIDEO_LENGTH,
        width: 480,
        height: 864,
        fps: run.fps,
      }),
      undefined,
      undefined,
      undefined, // loraJson
      undefined, // notifyJson
    );
    console.log(`  renderId=${renderId}`);
    check(`${run.label}: renderId non-empty`, renderId.length > 0, renderId);
    let result: any;
    try {
      result = await pollUntilDone(agent, renderId);
    } catch (err) {
      check(`${run.label}: render succeeded`, false, String(err));
      continue;
    }
    check(`${run.label}: render succeeded`, result.phase === "succeeded", `phase=${result.phase}`);
    if ((result.outputs?.length ?? 0) === 0) {
      check(`${run.label}: outputs present`, false, JSON.stringify(result.outputs));
      continue;
    }
    for (const out of result.outputs) {
      console.log(`  ${out.filename ?? out.name ?? "output"}: ${out.url}`);
      const r = await fetch(out.url);
      check(`${run.label}: ${out.name ?? out.filename} accessible`, r.ok, `HTTP ${r.status}`);
      const raw = Buffer.from(await r.arrayBuffer());
      check(`${run.label}: ${out.name ?? out.filename} is MP4`, _isMp4(raw), `magic=${_hexHead(raw)}`);
      checkFpsSnap(run.label, raw, run.fps, VIDEO_LENGTH);
    }
  }

  console.log(
    `\n=== ${failures.length === 0 ? "ALL CHECKS PASSED ✓" : failures.length + " CHECK(S) FAILED ✗"} ===`,
  );
  if (failures.length > 0) for (const f of failures) console.log(`  ✗ ${f}`);
} finally {
  await teardownAll();
  if (failures.length > 0)
    throw new Error(
      `${failures.length} e2e check(s) failed:\n${failures.join("\n")}`,
    );
}
